code.java:
public int pageCount(int n, int p) {
    int front = 0;
    while (2 * front + 1 < p) {   // flip forward until page p is on the spread
        front++;
    }
    int back = n / 2 - front;    // remaining sheets reach p from the back
    return Math.min(front, back);
}

code.python:
def pageCount(n: int, p: int) -> int:
    front = 0
    while 2 * front + 1 < p:   # flip forward until page p is on the spread
        front += 1
    back = n // 2 - front      # remaining sheets reach p from the back
    return min(front, back)

