public int pageCount(int n, int p) {
    int fromFront = p / 2;
    int fromBack = n / 2 - p / 2;
    return Math.min(fromFront, fromBack);
}

code.python:
def pageCount(n: int, p: int) -> int:
    from_front = p // 2
    from_back = n // 2 - p // 2
    return min(from_front, from_back)

